INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q7510172', 'Siege of Kuju', 'The siege of Kuju (Korean: 귀주성전투) which occurred in 1231 was a decisive Goryeo victory against the Mongol Empire during the First Mongol Invasion of Korea. After the Mongol army crossed the Yalu river, it quickly captured almost all of Goryeo''s border defenses.', 1231, NULL, NULL, 1232, 1, NULL, 'year', '1231 – January 1232', 39, 'https://en.wikipedia.org/wiki/Siege_of_Kuju'),
  ('Q3420016', 'Siege of Pyongyang', 'The siege of Pyongyang was part of the Japanese invasions of Korea. Konishi Yukinaga, a Japanese daimyō, captured Pyongyang and garrisoned his force there in the winter of 1592.', 1592, 7, 19, 1592, 7, 24, 'day', '19 July 1592 – 24 July 1592', 43, 'https://en.wikipedia.org/wiki/Siege_of_Pyongyang_(1592)'),
  ('Q4871272', 'Battle of Imjin River', 'The Battle of Imjin River (Japanese: 臨津江の戦い) was a battle during the 1592 Japanese invasion of Korea. Kim Myŏngwŏn''s northern defense was defeated and the Japanese were able to cross over and invade northern Korea.', 1592, 7, 7, NULL, NULL, NULL, 'day', '7 July 1592', 47, 'https://en.wikipedia.org/wiki/Battle_of_Imjin_River_(1592)'),
  ('Q14475856', 'Siege of Pyongyang', 'The siege of Pyongyang was a military conflict fought between the allied Ming-Joseon army and the Japanese First Division under Konishi Yukinaga, who were besieged in the city of Pyongyang. The battle ended in victory for the allies although remnants of the Japanese forces successfully escaped from the city in the night of 8 February 1593.', 1593, 2, 6, 1593, 2, 8, 'day', '6 February 1593 – 8 February 1593', 45, 'https://en.wikipedia.org/wiki/Siege_of_Pyongyang_(1593)'),
  ('Q715791', 'Battle of Pyongyang', 'The Battle of Pyongyang (Japanese: 平壌作戦; Chinese: 平壤之戰) was the second major land battle of the First Sino-Japanese War. It took place on 15 September 1894 in Pyongyang, Korea between the forces of Japan and the Qing dynasty of China.', 1894, 9, 15, NULL, NULL, NULL, 'day', '15 September 1894', 58, 'https://en.wikipedia.org/wiki/Battle_of_Pyongyang_(1894)'),
  ('Q575510', 'Battle of Pochonbo', 'Battle of Pochonbo (Korean: 보천보 전투; Hanja: 普天堡 戰鬪; RR: Bocheonbo Seubgyeog; Japanese: 普天堡の戦い, romanized: Futenho no Tatakai) was an event which occurred in northern Korea, Empire of Japan on 4 June 1937, when Korean and Chinese guerrillas commanded by Kim Il Sung (or possibly Choe Hyon) attacked and defeated a Japanese detachment during the anti-Japanese armed struggle in Korea. The battle holds an important place in North Korea.', 1937, 6, 4, NULL, NULL, NULL, 'day', '4 June 1937', 47, 'https://en.wikipedia.org/wiki/Battle_of_Pochonbo'),
  ('Q4448392', 'Seishin Operation', 'The Seishin Operation (Russian: Сэйсинская операция, romanized: Seysinskaya operatsiya, Korean: 청진 상륙 작전), also called Chongjin Landing Operation, was an amphibious assault on northern Korea (present day North Korea) over 490 miles from Pyongyang between 13–16 August 1945, carried out by the forces of the Soviet Northern Pacific Flotilla of the Pacific Fleet during the Soviet–Japanese War at the end of World War II.', 1945, 8, 17, NULL, NULL, NULL, 'day', '17 August 1945', 37, 'https://en.wikipedia.org/wiki/Seishin_Operation'),
  ('Q8663', 'Korean War', 'The Korean War (25 June 1950 – 27 July 1953) was an armed conflict fought on the Korean Peninsula between North Korea (Democratic People''s Republic of Korea; DPRK) and South Korea (Republic of Korea; ROK) and their allies. North Korea was supported by China and the Soviet Union, while South Korea was supported by the United Nations led by the United States under the auspices of the United Nations Command (UNC).', 1950, 6, 25, 1953, 7, 27, 'day', '25 June 1950 – 27 July 1953', 94, 'https://en.wikipedia.org/wiki/Korean_War'),
  ('Q277337', 'Battle of Changjin Reservoir', 'The Battle of Chosin Reservoir, also known as the Chosin Reservoir Campaign or the Battle of Lake Changjin (Korean: 장진호 전투; Hanja: 長津湖戰鬪; MR: Changjinho chŏnt''u), was a battle in the Korean War. The name "Chosin" is derived from the Japanese pronunciation "Chōshin", instead of the Korean pronunciation.', 1950, 11, 27, 1950, 12, 13, 'day', '27 November 1950 – 13 December 1950', 57, 'https://en.wikipedia.org/wiki/Battle_of_Chosin_Reservoir'),
  ('Q289102', 'Battle of Korea Strait', 'The Battle of Korea Strait (Korean: 대한해협 해전; Hanja: 大韓海峽海戰; RR: daehanhaehyeop haejeon; MR: taehanhaehyŏp haejŏn) was a single ship action fought on the first day of the Korean War on 25–26 June 1950, between the navies of South Korea and North Korea. A North Korean troop transport carrying hundreds of soldiers attempted to land its invasion force near Busan but was encountered by the South Korean patrol ship ROKS Baekdusan and sunk.', 1950, 6, 26, NULL, NULL, NULL, 'day', '26 June 1950', 45, 'https://en.wikipedia.org/wiki/Battle_of_Korea_Strait'),
  ('Q482979', 'Battle of Pusan Perimeter', 'The Battle of the Pusan Perimeter, known in Korean as the Battle of the Naktong River Defense Line (Korean: 낙동강 방어선 전투), was a large-scale battle between United Nations Command (UN) and North Korean forces lasting from August 4 to September 18, 1950. It was one of the first major engagements of the Korean War.', 1950, 8, 4, 1950, 9, 18, 'day', '4 August 1950 – 18 September 1950', 57, 'https://en.wikipedia.org/wiki/Battle_of_the_Pusan_Perimeter'),
  ('Q484494', 'Battle of Osan', 'The Battle of Osan (Korean: 오산 전투) was the first engagement between the United States and North Korea during the Korean War. On July 5, 1950, Task Force Smith, an American task force of 540 infantry supported by an artillery battery, was moved to Osan, south of Seoul, the capital of South Korea, and was ordered to fight as a rearguard to delay the advancing North Korean forces while more US troops arrived to form a stronger defensive line to the south.', 1950, 7, 4, NULL, NULL, NULL, 'day', '4 July 1950', 52, 'https://en.wikipedia.org/wiki/Battle_of_Osan'),
  ('Q493313', 'Battle of the Ch''ongch''on River', 'The Battle of the Ch''ongch''on River (Chinese: 清川江战役; pinyin: Qīngchuānjiāng Zhànyì), also known as the Battle of the Ch''ongch''on, was a battle in the Korean War that took place from November 25 to December 2, 1950, along the Ch''ongch''on River Valley in the northwestern part of North Korea. In response to the successful Chinese First Phase Offensive against the United Nations (UN) forces, General Douglas MacArthur launched the Home-by-Christmas Offensive to expel the Chinese forces from Korea and to end the war.', 1950, 11, 25, 1950, 12, 2, 'day', '25 November 1950 – 2 December 1950', 47, 'https://en.wikipedia.org/wiki/Battle_of_the_Ch''ongch''on_River'),
  ('Q4871363', 'Battle of Kaesong–Munsan', 'The Battle of Kaesong–Munsan–Bongilcheon (Hangul: 개성–문산–봉일천 전투; Hanja: 開城–汶山–奉日川 戰鬪) was a series of battles that occurred along the western region of the 38th parallel between 25 and 28 June 1950, as part of Operation Pokpoong (North Korea) and Operation Western Region (South Korea) that marked the beginning of the Korean War.', 1950, 6, 25, 1950, 6, 26, 'day', '25 June 1950 – 26 June 1950', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kaesong%E2%80%93Munsan'),
  ('Q6808488', 'Battle of Pyongyang (1950)', 'The Battle of Pyongyang (17–19 October 1950) was one of the major battles of the United Nations'' offensive during the Korean War. Following the Battle of Inchon, the UN forces re-captured Seoul, the capital of South Korea, and proceeded to advance into North Korea.', 1950, 10, 20, 1950, 10, 19, 'day', '20 October 1950 – 19 October 1950', 37, 'https://en.wikipedia.org/wiki/Battle_of_Pyongyang_(1950)'),
  ('Q489561', 'Battle of Heartbreak Ridge', 'The Battle of Heartbreak Ridge (Korean: 단장의 능선 전투; Hanja: 斷腸의 稜線 戰鬪; French: Bataille de Crèvecœur), also known as the Battle of Wendengli (Chinese: 文登里战斗; pinyin: Wéndēnglǐ Zhàndòu), was a month-long battle in the Korean War which took place between 13 September and 15 October 1951. After withdrawing from Bloody Ridge, the Korean People''s Army (KPA) set up new positions just 1,500 yards (1,400 m) away on a 7-mile (11 km) long hill mass.', 1951, 9, 13, 1951, 10, 15, 'day', '13 September 1951 – 15 October 1951', 45, 'https://en.wikipedia.org/wiki/Battle_of_Heartbreak_Ridge'),
  ('Q2889283', 'First Battle of Maryang-san', 'The First Battle of Maryang-san (3–8 October 1951), also known as the Defensive Battle of Maliangshan (Chinese: 馬良山防衛戰; pinyin: Mǎliáng Shān Fángyù Zhàn), was fought during the Korean War between United Nations Command (UN) forces—primarily Australian, British and Canadian—and the Chinese People''s Volunteer Army (PVA). The fighting occurred during a limited UN offensive by US I Corps, codenamed Operation Commando.', 1951, 10, 8, NULL, NULL, NULL, 'day', '8 October 1951', 37, 'https://en.wikipedia.org/wiki/First_Battle_of_Maryang-san'),
  ('Q16170016', 'Battle of the Imjin River', 'The Battle of the Imjin River, also known as the Battle of Solma-ri (Korean: 설마리 전투) or Battle of Gloster Hill (글로스터 고지 전투) in South Korea, or as Battle of Xuemali (Chinese: 雪马里战斗; pinyin: Xuě Mǎ Lǐ Zhàn Dòu) in China, took place 22–25 April 1951 during the Korean War. Troops from the Chinese People''s Volunteer Army (PVA) attacked United Nations Command (UN) positions on the lower Imjin River in an attempt to achieve a breakthrough and recapture the South Korean capital Seoul.', 1951, 4, 22, 1951, 4, 25, 'day', '22 April 1951 – 25 April 1951', 37, 'https://en.wikipedia.org/wiki/Battle_of_the_Imjin_River'),
  ('Q493295', 'Battle of Kumsong', 'The Battle of Kumsong, also known as the Jincheng Campaign (Chinese: 金城战役; pinyin: Jīn Chéng Zhàn Yì), was one of the last battles of the Korean War. During the ceasefire negotiations seeking to end the Korean War, the United Nations Command (UNC) and Chinese and North Korean forces were unable to agree on the issue of prisoner repatriation.', 1953, 7, 13, 1953, 7, 27, 'day', '13 July 1953 – 27 July 1953', 39, 'https://en.wikipedia.org/wiki/Battle_of_Kumsong'),
  ('Q2862267', 'Korean Armistice Agreement', 'The Korean Armistice Agreement (Korean: 한국정전협정; Hanja: 韓國停戰協定) is an armistice that brought about a cessation of hostilities of the Korean War. It was signed by United States Army Lieutenant General William Harrison Jr.', 1953, 7, 27, NULL, NULL, NULL, 'day', '27 July 1953', 65, 'https://en.wikipedia.org/wiki/Korean_Armistice_Agreement'),
  ('Q8740', 'Vietnam War', 'The Vietnam War (c. 1955 – 30 April 1975) was an armed conflict in Vietnam, Laos, and Cambodia fought between North Vietnam (Democratic Republic of Vietnam) and South Vietnam (Republic of Vietnam) and their allies. North Vietnam was supported by the Soviet Union and China, while South Vietnam was supported by the United States and other anti-communist nations.', 1975, 4, 30, 1975, 4, 30, 'day', '30 April 1975', 97, 'https://en.wikipedia.org/wiki/Vietnam_War'),
  ('Q796498', 'Third Indochina War', 'The Third Indochina War was a series of interconnected military conflicts among the various communist factions over strategic influence in mainland Southeast Asia after communist victory in South Vietnam, Laos, and Cambodia in 1975. The conflict primarily started due to continued raids and incursions by the Khmer Rouge into Vietnamese territory that they sought to retake.', 1975, 5, 1, 1991, 10, 23, 'day', '1 May 1975 – 23 October 1991', 53, 'https://en.wikipedia.org/wiki/Third_Indochina_War'),
  ('Q11401900', 'Frunze Military Academy Incident', 'A group of North Korean students planned to use a tank loaded with a live shell during a military parade officially commemorating the 60th anniversary of the Korean People''s Army on 25 April 1992, with the intention to fire it on the tribune as the vehicle passed the reviewing stand to kill North Korean leader Kim Il Sung and his son Kim Jong Il, as well as members of the country''s top leadership. The plan failed after one of the department chiefs in the Ministry of the People''s Armed Forces switched the tanks used in the parade to be from the Ministry instead of the capital defense division.', 1992, 4, 25, 1994, NULL, NULL, 'day', '25 April 1992 – 1994', 30, 'https://en.wikipedia.org/wiki/1992_North_Korean_coup_attempt'),
  ('Q698323', 'North Korean famine', 'The North Korean famine (Korean: 조선기근), dubbed by the government as the Arduous March (고난의 행군), was a period of mass starvation together with a general economic crisis from 1994 to 1999 in North Korea. During this time there was an increase in defection from North Korea, which peaked towards the end of the famine period.', 1994, NULL, NULL, 2000, NULL, NULL, 'year', '1994–2000', 65, 'https://en.wikipedia.org/wiki/1990s_North_Korean_famine'),
  ('Q4606729', '2006 North Korean floods', 'Flooding in North Korea in July 2006 caused extensive damage and loss of life, although reports differ about its extent.', 2006, 7, NULL, NULL, NULL, NULL, 'month', 'July 2006', 34, 'https://en.wikipedia.org/wiki/2006_North_Korean_floods'),
  ('Q1795430', '2007 North Korean floods', 'Flooding in North Korea in August 2007 caused extensive damage and loss of life. The flooding affected most of the southern half of the country including the capital and some of its most productive agricultural regions.', 2007, 8, NULL, NULL, NULL, NULL, 'month', 'August 2007', 37, 'https://en.wikipedia.org/wiki/2007_North_Korean_floods'),
  ('Q2741550', '2010 China floods', 'Floods in China in 2010 resulted in over 3,000 deaths. Three hundred and ninety-two people died, and a further 232 people were reported missing as of June 30, 2010, including 57 people in a landslide in Guizhou.', 2010, 5, 10, 2010, 9, NULL, 'day', '10 May 2010 – September 2010', 45, 'https://en.wikipedia.org/wiki/2010_China_floods'),
  ('Q902698', '2012 North Korean floods', 'The 2012 North Korean floods began in mid-July 2012 when Tropical Storm Khanun affected parts of the country, killing at least 88 people and leaving more than 62,000 people homeless. Torrential rains on 29 and 30 July 2012 worsened the situation, causing additional damage and casualties and forcing the government to request international assistance.', 2012, 7, 19, NULL, NULL, NULL, 'day', '19 July 2012', 34, 'https://en.wikipedia.org/wiki/2012_North_Korean_floods'),
  ('Q36281356', '2017–18 North Korea crisis', 'The 2017–2018 North Korea crisis was a period of heightened tension between North Korea and the United States. The crisis began early in 2017 when North Korea conducted a series of missile and nuclear tests that demonstrated the country''s ability to launch ballistic missiles beyond its immediate region, suggesting their nuclear weapons capability was developing at a faster rate than had been assessed by U.S. intelligence.', 2017, 4, 8, NULL, NULL, NULL, 'day', '8 April 2017', 55, 'https://en.wikipedia.org/wiki/2017%E2%80%932018_North_Korea_crisis'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q126896555', 'North Korean–Russian Treaty on Comprehensive Strategic Partnership', 'The Treaty on Comprehensive Strategic Partnership between the Russian Federation and the Democratic People''s Republic of Korea (Russian: Договор о всеобъемлющем стратегическом партнёрстве между Россией и КНДР, Korean: 조선민주주의인민공화국과 로씨야련방사이의 포괄적인 전략적동반자관계에 관한 조약) is a security and defense treaty between North Korea and Russia. It was signed on 18 June 2024 during a visit by Russian president Vladimir Putin to North Korea.', 2024, 6, 19, NULL, NULL, NULL, 'day', '19 June 2024', 50, 'https://en.wikipedia.org/wiki/North_Korean%E2%80%93Russian_Treaty_on_Comprehensive_Strategic_Partnership');
